#!/usr/bin/env bash
# Small polyglot repository for the comment-cleanup behaviour case: a mix of protected,
# machine-read directive comments (must survive byte-identical) and ordinary stale comments
# (dates, phase/ticket references, author names) that should be rewritten or removed.
set -euo pipefail
mkdir -p src/py src/go src/web src/gen

cat > src/py/app.py <<'PY'
"""Small polyglot fixture module for the comment-cleanup eval."""
import os


def load_config(path):  # noqa: E501
    # TODO(alice): revisit this after the 2019 migration to the new config loader.
    with open(path) as f:
        return f.read()


def parse(value):
    result = value.strip()  # type: ignore[no-any-return]
    return result
PY

cat > src/go/build_linux.go <<'GO'
//go:build linux
// +build linux

package pkg

// added in v2.3, moved from utils.go -- kept for backward compatibility, see ticket ORD-412
func Platform() string {
	return "linux"
}
GO

cat > src/web/bundle.config.js <<'JS'
// eslint-disable-next-line no-unused-vars
const unused = 1;

/* webpackChunkName: "vendor" */
import('./vendor');

// this file was added during the sprint 14 refactor by the platform team
module.exports = {};

//# sourceMappingURL=bundle.config.js.map
JS

cat > src/gen/schema.py <<'PY'
# @generated by codegen tool - do not edit by hand
class Schema:
    pass
PY

python3 - <<'PYEOF'
import json
snapshot = {
    "src/py/app.py": [
        "def load_config(path):  # noqa: E501",
        "    result = value.strip()  # type: ignore[no-any-return]",
    ],
    "src/go/build_linux.go": [
        "//go:build linux",
    ],
    "src/web/bundle.config.js": [
        "// eslint-disable-next-line no-unused-vars",
        '/* webpackChunkName: "vendor" */',
        "//# sourceMappingURL=bundle.config.js.map",
    ],
    "src/gen/schema.py": [
        "# @generated by codegen tool - do not edit by hand",
    ],
}
with open("directives_snapshot.json", "w") as f:
    json.dump(snapshot, f, indent=2)
    f.write("\n")
PYEOF

cat > check_directives.py <<'PY'
#!/usr/bin/env python3
"""Verify every protected directive comment recorded in directives_snapshot.json is still
present, byte-identical, in its file. Prints DIRECTIVES_INTACT and exits 0 if so, else prints
DIRECTIVES_CHANGED and exits 1."""
import json
import pathlib
import sys

HERE = pathlib.Path(__file__).parent
snapshot = json.loads((HERE / "directives_snapshot.json").read_text())

ok = True
for relpath, lines in snapshot.items():
    path = HERE / relpath
    if not path.exists():
        ok = False
        continue
    current_lines = path.read_text().splitlines()
    for expected in lines:
        if expected not in current_lines:
            ok = False

print("DIRECTIVES_INTACT" if ok else "DIRECTIVES_CHANGED")
sys.exit(0 if ok else 1)
PY

git init -q && git add -A && git -c user.email=dev@example.com -c user.name=dev commit -qm "polyglot fixture with protected directive comments"
